 config.MusicSongPreferences=new[]{new SongMusicPreference{Id="123",Mode="lively"},new SongMusicPreference{Id="123",Mode="quiet"},new SongMusicPreference{Id="bad",Mode="lively"}};config.Validate();Check(config.MusicSongPreferences.Length==1&&config.MusicSongPreferences[0].Mode=="quiet","偏好去重并校验歌曲 ID");var transferred=PreferenceTransfer.Import(PreferenceTransfer.Export(config,false));Check(transferred.MusicSongPreferences[0].Mode=="quiet","按歌曲偏好可以迁移");
 foreach(string skin in new[]{"kiana-winter-wish-round","kiana-fiery-wishing-star-round","time-runner-kiana-round"}){var frames=MusicSprites.Load(skin);Check(frames!=null&&frames.Length==24&&frames.All(f=>f.PixelWidth==768&&f.PixelHeight==832),"24 帧与脸宽归一化："+skin);foreach(var frame in frames){VerifyFrameEdges(frame);var bgra=new FormatConvertedBitmap(frame,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[frame.PixelWidth*frame.PixelHeight*4];bgra.CopyPixels(pixels,frame.PixelWidth*4,0);Check(pixels[3]==0&&pixels[(frame.PixelWidth-1)*4+3]==0,"图集角落保持实际透明");}pet.SelectSkin(skin);Set(pet,"state","music-lively");Set(pet,"lastFrame",-1);Call(pet,"DrawAnimation",0d);Check(ReferenceEquals(((Image)Field(pet,"sprite")).Source,frames[12])&&Field(pet,"activeAlignment")==null,"新动作不套用旧动作缩放："+skin);}
 SeatedFrameTests();ContactSheet();QualitySheets();var otherSkinPreview=new MusicAnimationPreview("kiana-winter-wish-round","quiet");otherSkinPreview.Show();var liveSkin=MusicSprites.Load("time-runner-kiana-round");await Task.Delay(160);Check(ReferenceEquals(liveSkin,MusicSprites.Load("time-runner-kiana-round")),"Different skin preview retains its cache without evicting live pet frames");otherSkinPreview.Close();pet.Music.Current=state;state.Playing=true;state.Position=20;state.At=DateTime.UtcNow;pet.SetSongMusicMode("gentle");pet.MarkMusicChorus(false);state.Position=55;pet.MarkMusicChorus(true);var saved=MusicReactions.Preference(Store.Load(),"123");Check(saved.Mode=="gentle"&&saved.Start>=20&&saved.End>=55,"真实设置入口保存本曲模式和区间");pet.ClearMusicChorus();Check(MusicReactions.Preference(pet.Settings,"123").Start==-1,"可清除手动区间并恢复远程时间");
 w.NavigateCategory("音乐","音乐动作");w.UpdateStatus();w.Capture(Path.Combine(Store.Root,"music-reaction-settings.png"));Check(w.ActiveCategory=="音乐"&&((TextBlock)Field(w,"musicReactionStatus")).Text.Contains("轻微挥棒"),"设置展示当前模式与来源");ChorusUiTests(pet,w);SessionUiTests(pet,w);string before=File.ReadAllText(Path.Combine(Store.Root,"settings.json"));pet.PreviewMusicAnimation("gentle");await Task.Delay(180);var preview=app.Windows.OfType<MusicAnimationPreview>().Single();Check(preview.Sprite.Source!=null,"动作预览显示实际素材");preview.Close();Check(before==File.ReadAllText(Path.Combine(Store.Root,"settings.json")),"预览不修改偏好");var music=new MusicWindow(pet);music.Show();pet.OpenMusicReactionMenu(music);await Task.Delay(100);var menu=(ContextMenu)Field(pet,"toolbarMenu");Check(menu.IsOpen&&((MenuItem)menu.Items[0]).IsEnabled,"音乐栏菜单真实打开且可设置本曲");var songMenu=(MenuItem)menu.Items[0];((MenuItem)((MenuItem)songMenu.Items[1]).Items[4]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(MusicReactions.Preference(pet.Settings,"123").ChorusAction=="lively","菜单活力应援选项保存本曲偏好");Call(pet,"ClosePetMenu");music.Close();passed=true;
 }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString()});}finally{Store.Atomic("music-reaction-tests.json",new{passed,checks});foreach(var window in app.Windows.Cast<Window>().Where(window=>window!=pet).ToArray())window.Close();pet.Close();}};app.Run(pet);return passed?0:1;
